sys_script_include.script:
var Criteria = Class.create();
Criteria.prototype = {
    initialize: function() {},

    criteriaBase: function() {
        var availableBases = [];
        var grBase = new GlideRecord('x_1593193_bases_bases');


        grBase.addEncodedQuery('available_capacity!=0');
        grBase.query();
        while (grBase.next()) {
            availableBases.push(grBase.getUniqueValue());
        }

        var userID = gs.getUserID();
        var grbaseCheckin = new GlideRecord('x_1593193_bases_checkin');


        grbaseCheckin.addQuery('opened_by', userID);
        grbaseCheckin.addQuery('state', '!=', '4');
        grbaseCheckin.query();

        if (grbaseCheckin.hasNext()) {

            return 'sys_idINNULL';
        }

        return 'sys_idIN' + availableBases.join(',');
    },

    type: 'Criteria'
};
